// --- the tail of src/data/auras.js, pasted in by gen_round115_auras.mjs -----
//
// Everything below is logic rather than data, so it lives here and is copied
// verbatim into the generated file. Keeping it out of the generator's string
// soup means it is ordinary readable JavaScript that an editor can lint.

export const AURA_KEYS = Object.keys(AURAS);
export const AURA_LIST = AURA_KEYS.map(k => AURAS[k]);

/**
 * The aura as it stands at `rank`.
 *
 * A straight read, because each rank's spec is already the full state (see the
 * header). `gained` is the ladder of card lines up to and including this rank,
 * which is what a tooltip prints when it wants to show what the aura has
 * become rather than only what it last did.
 */
export function specAtRank(key, rank) {
  const a = AURAS[key];
  if (!a || RANK_INDEX[rank] === undefined) return null;
  const gained = [];
  for (const r of AURA_RANKS) {
    if (a.ranks[r]) gained.push({ rank: r, adds: a.ranks[r].adds });
    if (r === rank) break;
  }
  const top = a.ranks[rank] || {};
  return {
    key: a.key, label: a.label, rank, spec: { ...top.spec }, gained,
    trigger: top.trigger || null, effect: top.effect || null,
    blurb: a.blurb, note: a.note || null,
  };
}

/** Every field this aura touches anywhere on its ladder. */
function usedFields(a) {
  const s = new Set();
  for (const r of AURA_RANKS) {
    const step = a.ranks[r];
    if (step) for (const k of Object.keys(step.spec || {})) s.add(k);
  }
  return [...s];
}

/**
 * Which auras an essence can roll, best first.
 *
 * The same shape `sensesFor` uses: an essence NAMED on the aura scores above
 * one that only matches its family, matching awakening stones lift it further,
 * and the seed only breaks ties. So stones steer which aura you get and the
 * family decides which are on the table at all.
 */
export function aurasFor(essenceId, { stones = [], seed = 0, count = 3 } = {}) {
  const ess = ESSENCE_CATALOG[essenceId];
  if (!ess) return [];
  const fams = new Set(stones.map(s => (STONE_CATALOG[s] && STONE_CATALOG[s].family) || s).filter(Boolean));
  const pool = AURA_LIST.filter(a =>
    (a.essences || []).includes(essenceId) || (a.families || []).includes(ess.family));
  const score = (a) => ((a.essences || []).includes(essenceId) ? 3 : 0)
    + (a.stones || []).filter(f => fams.has(f)).length * 2;
  return pool
    .slice()
    .sort((x, y) => (score(y) - score(x))
      || (frac(String(seed), essenceId, x.key) - frac(String(seed), essenceId, y.key)))
    .slice(0, count);
}

/** FNV-1a. `Math.imul` because a plain `*` loses the low bits past 2^53. */
function frac(...parts) {
  let h = 0x811c9dc5;
  const s = parts.join('|');
  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; }
  return h / 0x100000000;
}

/** Auras that touch nothing pending -- playable in full on the shipped build. */
export function liveOnly() {
  return AURA_LIST.filter(a => usedFields(a).every(f => AURA_FIELDS[f] && AURA_FIELDS[f].state === 'live'));
}

/** The reads that do not exist yet, with where each belongs and which auras
 *  are waiting on it. Empty as of round 115, and kept because the next batch
 *  of auras will arrive with its own. */
export function pendingRuntimeWork() {
  const need = new Map();
  for (const a of AURA_LIST) {
    for (const f of usedFields(a)) {
      if (!AURA_FIELDS[f] || AURA_FIELDS[f].state !== 'pending') continue;
      if (!need.has(f)) need.set(f, []);
      need.get(f).push(a.key);
    }
  }
  return [...need.entries()].sort((x, y) => y[1].length - x[1].length).map(([field, users]) => ({
    field, where: AURA_FIELDS[field].where, note: AURA_FIELDS[field].note, auras: users,
  }));
}

/**
 * Honest accounting, and deliberately not "how many auras are 100% live".
 *
 * The number that matters is `feltAtEveryRank`: whether a player who takes an
 * aura notices each rank-up. An aura whose gold rank consists entirely of
 * fields nothing reads is an aura that stops improving at silver, and the
 * player is never told which.
 */
export function auraStats() {
  return {
    auras: AURA_LIST.length,
    ranks: AURA_RANKS.length,
    rungs: AURA_LIST.length * AURA_RANKS.length,
    feltAtEveryRank: AURA_LIST.filter(a => AURA_RANKS.every((r, i) => i === 0 || rankChangesLive(a, i))).length,
    fullyLive: liveOnly().length,
    newFields: pendingRuntimeWork().length,
    overPromisedRungs: overPromisedRungs().length,
    playableToday: AURA_LIST.filter(a => readiness(a.key) === 'playable').length,
    blockedOnOneRead: AURA_LIST.filter(a => readiness(a.key) === 'blocked').length,
    triggered: AURA_LIST.filter(a => a.ranks.gold && a.ranks.gold.trigger).length,
    byEffect: AURA_LIST.reduce((acc, a) => {
      const e = a.ranks.normal.spec.auraEffect;
      acc[e] = (acc[e] || 0) + 1; return acc;
    }, {}),
  };
}

/** The pending fields a rank INTRODUCES -- which is to say, the part of that
 *  rank's card line that is not true yet. */
export function pendingAtRank(key, rank) {
  const a = AURAS[key];
  if (!a) return [];
  const i = RANK_INDEX[rank];
  const before = i === 0 ? {} : (a.ranks[AURA_RANKS[i - 1]] || {}).spec || {};
  const step = a.ranks[rank] || {};
  return Object.keys(step.spec || {}).filter(k =>
    !(k in before) && AURA_FIELDS[k] && AURA_FIELDS[k].state === 'pending');
}

/** Every rung whose card line describes something the runtime cannot do yet. */
export function overPromisedRungs() {
  const out = [];
  for (const a of AURA_LIST) {
    for (const r of AURA_RANKS) {
      const p = pendingAtRank(a.key, r);
      if (p.length) out.push({ aura: a.key, rank: r, fields: p, adds: a.ranks[r].adds });
    }
  }
  return out;
}

/**
 * 'playable'  the NORMAL rank is true on the shipped build. You can roll this
 *             aura and the card does not lie about what you just got.
 * 'blocked'   the normal rank itself names a field with no read, because the
 *             rider IS the concept -- a drain field that does not drain.
 */
export function readiness(key) {
  return pendingAtRank(key, 'normal').length ? 'blocked' : 'playable';
}

/**
 * The cheapest order to do any remaining runtime work in: for each pending
 * field, how many auras it UNBLOCKS and how many it COMPLETES. Empty as of
 * round 115; this is the tool the next batch is planned with.
 */
export function cheapestWins() {
  const fields = PENDING_FIELDS.filter(f => AURA_LIST.some(a => usedFields(a).includes(f)));
  return fields.map((f) => {
    const unblocks = AURA_LIST.filter(a => pendingAtRank(a.key, 'normal').includes(f)).length;
    const completes = AURA_LIST.filter(a => {
      const p = usedFields(a).filter(k => AURA_FIELDS[k].state === 'pending');
      return p.length === 1 && p[0] === f;
    }).length;
    const touched = AURA_LIST.filter(a => usedFields(a).includes(f)).length;
    return { field: f, where: AURA_FIELDS[f].where, unblocks, completes, touched };
  }).sort((a, b) => (b.completes - a.completes) || (b.unblocks - a.unblocks) || (b.touched - a.touched));
}

/** Does rank `i` change at least one field the runtime actually reads? */
function rankChangesLive(a, i) {
  const lo = a.ranks[AURA_RANKS[i - 1]].spec, hi = a.ranks[AURA_RANKS[i]].spec;
  for (const k of Object.keys(hi)) {
    if (!AURA_FIELDS[k] || AURA_FIELDS[k].state !== 'live') continue;
    if (JSON.stringify(lo[k]) !== JSON.stringify(hi[k])) return true;
  }
  return false;
}

/**
 * Everything this file promises, checked.
 *
 * The generator asserts all of this before it writes, so a run that got here
 * cannot fail -- which is exactly why this exists as well. The generator
 * guards the CSV; this guards the FILE, and the file is what ships. Somebody
 * editing the generated table by hand (which the header asks them not to do,
 * which is not the same as it not happening) gets caught by the data suite
 * rather than by a player.
 */
export function auraFaults() {
  const out = [];
  const PLAYABLE = new Set(ESSENCE_IDS);
  const kinds = new Set(TRIGGER_KINDS);
  const effects = new Set(TRIGGER_EFFECT_KINDS);
  const liveEffects = new Set(AURA_LIVE_EFFECTS);

  for (const a of AURA_LIST) {
    if (!a.label) out.push(`${a.key}: no label`);
    if (!a.blurb) out.push(`${a.key}: no blurb`);

    for (const r of AURA_RANKS) {
      const step = a.ranks[r];
      if (!step) { out.push(`${a.key}: no ${r} rank`); continue; }
      if (!step.adds) out.push(`${a.key}.${r}: nothing said about what it adds`);
      if (!step.spec || !Object.keys(step.spec).length) out.push(`${a.key}.${r}: grants nothing`);
      for (const f of Object.keys(step.spec || {})) {
        if (!AURA_FIELDS[f]) out.push(`${a.key}.${r}: "${f}" is not a field this file declares`);
      }
    }
    if (!a.ranks.normal || !a.ranks.gold) continue;

    const eff = a.ranks.normal.spec.auraEffect;
    if (!liveEffects.has(eff)) {
      out.push(`${a.key}: auraEffect "${eff}" has no branch in _updatePassiveEffects — the aura would be inert`);
    }
    for (const r of AURA_RANKS) {
      const e2 = a.ranks[r] && a.ranks[r].spec && a.ranks[r].spec.auraEffect;
      if (e2 && e2 !== eff) out.push(`${a.key}.${r}: auraEffect changes to "${e2}" mid-ladder`);
    }

    for (let i = 1; i < AURA_RANKS.length; i++) {
      if (!a.ranks[AURA_RANKS[i - 1]] || !a.ranks[AURA_RANKS[i]]) continue;
      if (!rankChangesLive(a, i)) {
        out.push(`${a.key}: ${AURA_RANKS[i]} changes nothing the runtime reads — an unfelt rank-up`);
      }
      const lo = a.ranks[AURA_RANKS[i - 1]].spec, hi = a.ranks[AURA_RANKS[i]].spec;
      for (const k of Object.keys(lo)) {
        if (!(k in hi)) out.push(`${a.key}.${AURA_RANKS[i]}: "${k}" was there at ${AURA_RANKS[i - 1]} and is gone`);
      }
    }

    const gold = a.ranks.gold;
    if (!gold.trigger) out.push(`${a.key}: gold has no triggered effect`);
    else {
      if (!kinds.has(gold.trigger.on)) out.push(`${a.key}: trigger "${gold.trigger.on}" is not a TRIGGER_KIND`);
      if (!gold.effect) out.push(`${a.key}: gold trigger fires nothing`);
      else if (!effects.has(gold.effect.kind)) {
        out.push(`${a.key}: effect "${gold.effect.kind}" is not a TRIGGER_EFFECT_KIND`);
      }
    }

    for (const r of AURA_RANKS) {
      const s = (a.ranks[r] || {}).spec || {};
      if (s.perAllyGain) {
        for (const k of Object.keys(s.perAllyGain)) {
          if (k !== 'resistPct' && k !== 'dotChancePct') {
            out.push(`${a.key}.${r}: perAllyGain."${k}" is not a kind _allyAuraBonus is ever called with`);
          }
        }
      }
      if (s.wardResist && !AURA_ELEMENTS.includes(s.wardResist.element)) {
        out.push(`${a.key}.${r}: wardResist element "${s.wardResist.element}" is not one of the six`);
      }
      for (const w of (s.wardResistExtra || [])) {
        if (!AURA_ELEMENTS.includes(w.element)) {
          out.push(`${a.key}.${r}: wardResistExtra element "${w.element}" is not one of the six`);
        }
      }
      if (s.element && !AURA_ELEMENTS.includes(s.element)) {
        out.push(`${a.key}.${r}: element "${s.element}" is not one _specElement will accept`);
      }
    }

    for (const e of a.essences || []) {
      if (!ESSENCE_CATALOG[e]) out.push(`${a.key}: essence "${e}" does not exist`);
      else if (!PLAYABLE.has(e)) out.push(`${a.key}: essence "${e}" is blocked and cannot be rolled`);
    }
  }

  for (const id of ESSENCE_IDS) {
    const n = aurasFor(id, { count: 99 }).length;
    if (!n) out.push(`${ESSENCE_CATALOG[id].name} (${ESSENCE_CATALOG[id].family}) can roll no aura at all`);
    else if (n < 3) {
      out.push(`${ESSENCE_CATALOG[id].name} (${ESSENCE_CATALOG[id].family}) reaches only ${n} aura${n === 1 ? '' : 's'} — no real choice`);
    }
  }

  for (const a of AURA_LIST) {
    const reach = ESSENCE_IDS.some(id =>
      (a.essences || []).includes(id) || (a.families || []).includes(ESSENCE_CATALOG[id].family));
    if (!reach) out.push(`${a.key}: no essence can roll it`);
  }
  return out;
}
